<script setup lang="ts">
import {ref,watch,onMounted,onBeforeUnmount} from 'vue';import {api,ApiError} from '../api';import type {WorkTab} from '../stores';import StoreGps from '../components/StoreGps.vue';import Modal from '../components/Modal.vue';
const props=defineProps<{tab:WorkTab}>();const form=ref<any>({store_code:'',store_name:'',short_name:'',hr_store_code:'',manager_name:'',address:'',phone:'',is_active:true,is_franchise:false,gps_latitude:'',gps_longitude:''}),error=ref(''),message=ref(''),loading=ref(false),locating=ref(false),version=ref(''),conflict=ref(false),canSave=ref(false),confirm=ref(false);let baseline=JSON.stringify(form.value),originalActive=true,pendingKey='',requestId='',resolver:((ok:boolean)=>void)|null=null;
watch(form,()=>{props.tab.dirty=JSON.stringify(form.value)!==baseline;message.value='';},{deep:true,flush:'sync'});
async function load(preserve=false){loading.value=true;error.value='';try{const d=await api('stores'+(props.tab.recordId?'?id='+props.tab.recordId:''));canSave.value=props.tab.recordId?d.capabilities.edit:d.capabilities.create;if(props.tab.recordId){const s=d.stores[0],next:any={};for(const k of Object.keys(form.value))next[k]=s[k]??'';baseline=JSON.stringify(next);version.value=s.version;originalActive=s.is_active;if(!preserve)form.value=next;props.tab.dirty=JSON.stringify(form.value)!==baseline;}conflict.value=false;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function answer(ok:boolean){confirm.value=false;resolver?.(ok);resolver=null;}
async function save(){if(!canSave.value||loading.value||locating.value||props.tab.busy||conflict.value)return false;error.value='';if(!form.value.store_name.trim()||(!props.tab.recordId&&!form.value.store_code.trim())){error.value='請填寫門市代碼與名稱';return false;}const lat=String(form.value.gps_latitude).trim()?Number(form.value.gps_latitude):null,lng=String(form.value.gps_longitude).trim()?Number(form.value.gps_longitude):null;if((lat===null)!==(lng===null)||(lat!==null&&(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng!)>180))){error.value='GPS 緯度與經度須成對，且在有效範圍內';return false;}if(props.tab.recordId&&originalActive&&!form.value.is_active){if(confirm.value)return false;const ok=await new Promise<boolean>(r=>{resolver=r;confirm.value=true;});if(!ok)return false;}
props.tab.busy=true;const data={...form.value,id:props.tab.recordId,gps_latitude:lat,gps_longitude:lng};const op=props.tab.recordId?'edit':'create';const key=JSON.stringify({op,data});if(key!==pendingKey){pendingKey=key;requestId=crypto.randomUUID();}try{const r=await api('stores',{method:'POST',body:JSON.stringify({operation:op,data,requestId,expected:version.value})});props.tab.recordId=r.id;props.tab.store=r.id;props.tab.title='編輯門市 · '+form.value.store_name;baseline=JSON.stringify(form.value);props.tab.dirty=false;await load();message.value=error.value?'門市已儲存，請重新載入確認最新內容':'門市資料已儲存';if(error.value)conflict.value=true;return true;}catch(e){error.value=(e as Error).message;conflict.value=e instanceof ApiError&&e.status===409&&error.value.includes('其他人');return false;}finally{props.tab.busy=false;}}
props.tab.save=save;onMounted(()=>load());onBeforeUnmount(()=>{answer(false);delete props.tab.save;});
</script><template><header class="page-heading"><div><p class="eyebrow">組織與門市 / 門市資料</p><h1>{{tab.recordId?'編輯門市':'新增門市'}}</h1></div><button :disabled="tab.busy||loading||locating||confirm" @click="load(tab.dirty)">{{tab.dirty?'重新載入（保留草稿）':'重新載入'}}</button></header><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="loading" role="status">載入門市資料…</p><p v-if="!loading&&!canSave" class="notice">目前為唯讀，沒有此門市編輯權限。</p><form v-if="canSave||(tab.recordId&&version)" @submit.prevent="save"><fieldset :disabled="!canSave||tab.busy||loading||locating||conflict||confirm"><div class="store-form"><label>門市代碼<input aria-label="門市代碼" v-model="form.store_code" required maxlength="20" :disabled="!!tab.recordId"><small v-if="tab.recordId">代碼變更請使用搬遷功能</small></label><label>門市名稱<input v-model="form.store_name" required maxlength="100"></label><label>簡稱<input v-model="form.short_name" maxlength="200"></label><label>人資門市代碼<input v-model="form.hr_store_code" maxlength="200"></label><label>負責人<input v-model="form.manager_name" maxlength="200"></label><label>電話<input v-model="form.phone" maxlength="20"></label><label class="wide">地址<input v-model="form.address" maxlength="2000"></label><label class="check"><input type="checkbox" v-model="form.is_franchise">加盟店</label><label v-if="tab.recordId" class="check"><input type="checkbox" v-model="form.is_active">營運中</label></div></fieldset><StoreGps :latitude="form.gps_latitude" :longitude="form.gps_longitude" :disabled="!canSave||tab.busy||loading||conflict||confirm" @latitude="form.gps_latitude=$event" @longitude="form.gps_longitude=$event" @locating="locating=$event"/><div class="dialog-actions"><button v-if="canSave" class="primary" :disabled="tab.busy||loading||locating||conflict||confirm||!tab.dirty">{{tab.busy?'儲存中…':'儲存門市'}}</button></div></form><Modal v-if="confirm" title="確認停止營運" @cancel="answer(false)"><p>將 {{form.store_code}} {{form.store_name}} 設為已停止，既有紀錄仍保留。</p><div class="dialog-actions"><button @click="answer(false)">返回編輯</button><button class="danger" @click="answer(true)">確認儲存</button></div></Modal></template><style scoped>fieldset{border:0;padding:0;min-width:0}.store-form{display:grid;grid-template-columns:1fr 1fr;gap:20px;max-width:1000px}label{display:grid;gap:8px}.wide{grid-column:1/-1}.check{display:flex;align-items:center}.check input{min-width:18px;min-height:18px;width:18px;height:18px}small{color:var(--muted)}input{min-width:0;width:100%}@media(max-width:650px){.store-form{grid-template-columns:1fr}}</style>
